/// Output of [`emit_document`].
#[derive(Debug, Clone)]
pub struct EmitOutput {
    pub typescript: String,
    /// The synthesized name we used for this file's render function — so
    /// callers (e.g. test code) can assert on it without re-deriving the
    /// hash.
    pub render_name: SmolStr,
    /// Line map: for each contiguous run of verbatim source content that
    /// landed in the overlay, an entry mapping the overlay line range
    /// back to the source line range.
    pub line_map: Vec<LineMapEntry>,
    /// Token map: byte-span entries mapping a specific synthesized span
    /// in the overlay back to a byte span in the `.svelte` source. Used
    /// by the diagnostic mapper to surface errors at user positions
    /// even when the overlay line the error landed on is inside
    /// synthesized scaffolding (the line is NOT covered by `line_map`).
    ///
    /// Entries are pushed by emit at each site that splices user
    /// source into synthesized scaffolding — template interpolations,
    /// component-call prop values, `bind:this` assignments, `$on`
    /// event-name literals. An empty vec is the current default
    /// (Item 1 plumbing only); emit sites will start pushing in the
    /// follow-up PRs (Items 2/3/4 of the v0.3 plan).
    pub token_map: Vec<TokenMapEntry>,
    /// Byte offsets of the start of each line in `typescript`. Entry N
    /// holds the byte offset where line N+1 begins (1-based line
    /// numbering: index 0 is the start of line 1). Appended is a
    /// sentinel equal to `typescript.len()` so a binary search can
    /// clamp the final line. Used to convert a tsgo `(line, column)`
    /// diagnostic position into an overlay byte offset for
    /// TokenMapEntry lookup.
    pub overlay_line_starts: Vec<u32>,
    /// Byte offsets of the start of each line in the `.svelte` source
    /// this overlay was emitted from. Same shape as
    /// `overlay_line_starts`. Used by the diagnostic mapper to
    /// convert a TokenMapEntry's `source_byte` span back into a
    /// 1-based (line, column) for the user-facing diagnostic.
    pub source_line_starts: Vec<u32>,
}

/// Single line mapping from the overlay back to the original `.svelte`
/// source. Both line numbers are 1-based.
///
/// Within `[overlay_start_line, overlay_end_line)`, line N maps to
/// source line `source_start_line + (N - overlay_start_line)`.
///
/// Lines that fall outside any entry's range are synthesized (header
/// comment, function wrapper, void block) and have no source mapping —
/// the diagnostic mapper clamps them to `source_start_line` of the
/// nearest preceding entry, or to line 1 if none exists.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LineMapEntry {
    pub overlay_start_line: u32,
    pub overlay_end_line: u32,
    pub source_start_line: u32,
}

/// Single byte-span mapping from a synthesized region of the overlay
/// back to a byte range in the `.svelte` source. Both ranges are
/// half-open `[start, end)` byte offsets.
///
/// TokenMapEntry lives alongside [`LineMapEntry`]: line-map covers
/// verbatim script blocks (where overlay line N trivially maps to
/// source line source_start + N - overlay_start), token-map covers
/// synthesized scaffolding where a specific overlay token was
/// spliced in from a specific source position (template `{expr}`
/// interpolations, `new __svn_C_N({...})` call sites with user-source
/// prop values, `bind:this` assignments, `$on` event-name literals).
///
/// The diagnostic mapper prefers the tightest-span TokenMapEntry
/// containing the diagnostic's byte offset; falls back to
/// LineMapEntry when no token-map match exists; drops the
/// diagnostic when neither matches (mirrors upstream svelte-check's
/// source-map-driven filter).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TokenMapEntry {
    pub overlay_byte_start: u32,
    pub overlay_byte_end: u32,
    pub source_byte_start: u32,
    pub source_byte_end: u32,
}

/// Emit the TypeScript scaffold for a parsed Svelte document.
///
/// `source_path` is used to derive a per-file unique render-function name
/// (hash of the canonical path). Callers without a real path (unit tests)
/// pass any stable string; the resulting hash will be identical for the
/// same input string, which is fine.
pub fn emit_document(
    doc: &Document<'_>,
    fragment: &Fragment,
    summary: &TemplateSummary,
    source_path: &Path,
) -> EmitOutput {
    emit_document_with_lang(doc, fragment, summary, source_path, true)
}

/// Like [`emit_document`] but lets the caller pick whether the overlay
/// is TypeScript (`is_ts = true` — `.svelte.svn.ts`, TS-strict
/// inference) or JavaScript (`is_ts = false` — `.svelte.svn.js`,
/// JS-loose inference under `checkJs:true + noImplicitAny:false`).
///
/// The CLI dispatches per-file based on the source's `<script lang=>`
/// attribute, mirroring upstream svelte-check's `isTsSvelte(text)`
/// dispatch in
/// `language-tools/packages/svelte-check/src/incremental.ts:213`.
/// Two effects flow from the choice:
///   - TS-only syntax (`!:` definite-assign, `as any` casts, function
///     generics, `declare const`, `interface`/`type` aliases) is
///     replaced with the equivalent JSDoc form for JS overlays.
///   - The `.svelte.svn.js` extension flips tsgo's per-file inference
///     mode — `let x = $state([])` widens to `any[]` in JS, stays
///     `never[]` in TS. Load-bearing for JSDoc-typed Props
///     components that wrap a third-party default export (the
///     CodeMirror integration pattern) and for any JSDoc-typed
///     Props component,
///     where tsgo natively reads `/** @typedef */` / `/** @type */`
///     annotations only under `.js`.
pub fn emit_document_with_lang(
    doc: &Document<'_>,
    fragment: &Fragment,
    summary: &TemplateSummary,
    source_path: &Path,
    is_ts: bool,
) -> EmitOutput {
    let render_name = render_function_name(source_path);
    emit_document_with_render_name(doc, fragment, summary, render_name, source_path, is_ts)
}

fn emit_document_with_render_name(
    doc: &Document<'_>,
    fragment: &Fragment,
    summary: &TemplateSummary,
    render_name: SmolStr,
    source_path: &Path,
    is_ts: bool,
) -> EmitOutput {
    // Set the thread-local so deep emit sites (bind:this casts,
    // each-block `let i`, branch bindings, snippet params) can branch
    // on TS-vs-JS overlay shape without threading `is_ts` through 9+
    // function signatures. Reset on scope exit via `IsTsGuard`.
    let _ts_guard = IsTsGuard::enter(is_ts);
    let estimated_capacity = doc.source.len().saturating_mul(2).saturating_add(256);
    let mut buf = EmitBuffer::with_capacity(estimated_capacity);

    buf.push_str("// generated by svelte-check-native; do not edit\n");

    // Module script content (already at module level — no special handling).
    let mut module_body: Option<std::ops::Range<usize>> = None;
    if let Some(module_script) = &doc.module_script {
        // Pad to a trailing `\n` before calling `append_verbatim` so a
        // single-line script (no terminating newline) still produces a
        // LineMapEntry — append_verbatim only emits one when the text
        // spans at least one newline, and we need source mapping for the
        // overlay region even if the script is one line. The padded `\n`
        // is synthetic filler, semantically equivalent to the old
        // separate `push_str("\n")` that previous code did afterwards.
        let padded;
        let text: &str = if module_script.content.ends_with('\n') {
            module_script.content
        } else {
            padded = format!("{}\n", module_script.content);
            &padded
        };
        // R-Conv #2: same TokenMapEntry treatment as the instance
        // script body — module-script content is verbatim from
        // source, so push a 1:1 byte-range token-map so single-line
        // scripts get column-accurate reverse-mapping.
        let body_no_pad = module_script.content.trim_end_matches('\n');
        let overlay_start = buf.raw_string_mut().len() as u32;
        buf.push_token_map(TokenMapEntry {
            overlay_byte_start: overlay_start,
            overlay_byte_end: overlay_start + body_no_pad.len() as u32,
            source_byte_start: module_script.content_range.start,
            source_byte_end: module_script.content_range.start + body_no_pad.len() as u32,
        });
        buf.append_verbatim(text, doc.source, module_script.content_range);
        module_body = Some(overlay_start as usize..overlay_start as usize + body_no_pad.len());
    }

    // `<script generics="T extends ...">` — pulled from the parser's
    // ScriptSection::generics. Extracted up front so process_instance_script_content can
    // decide whether to hoist bare `type`/`interface` declarations out
    // of the render body (they'd lose access to the `T` generic if
    // lifted to module scope).
    let generics_with_origin = extract_generics_attr(doc);
    let generics = generics_with_origin.as_ref().map(|(g, _)| g.clone());

    // Parse the instance script exactly once up front. Every analyze
    // pass that needs the oxc AST of the ORIGINAL script (Props type
    // source, declared props, top-level bindings, typed uninitialized
    // lets, typed top-level lets) derives its facts from this single
    // parse — each was its own reparse + allocator before, which
    // added up to 4-5 repeats of the same work on the hot path. The
    // `rewritten_content` reparse at bindings-collection time is
    // separate (different source string) and only fires when the
    // rewrite chain actually changed the script bytes — identity
    // chains collapse `rewritten_content` to None below.
    let alloc_instance = Allocator::default();
    let parsed_instance = doc
        .instance_script
        .as_ref()
        .map(|s| parse_script_body(&alloc_instance, s.content, s.lang));
    let alloc_module = Allocator::default();
    let parsed_module = doc
        .module_script
        .as_ref()
        .map(|s| parse_script_body(&alloc_module, s.content, s.lang));
    // AST-based event-dispatcher presence check — feeds the
    // default-export shape selection in `should_emit_fn_component_shape`.
    // Computing it here (where the parsed ASTs already exist) keeps
    // the decision off raw source-text scanning, which would
    // false-fire on comments / unused imports / string literals
    // containing the name. Mirrors upstream's `events.hasEvents()`
    // gate. See `has_event_dispatcher_call` in svn-analyze.
    // Reviewer follow-up #3 (round 5): scan only the instance
    // script. Upstream svelte2tsx's `processModuleScriptTag.ts:69`
    // does NOT feed `<script module>` declarations into
    // `ComponentEvents`, so a module-only `createEventDispatcher()`
    // shouldn't disqualify the Svelte 5 fn-component shape or
    // attach the `__svn_events` marker. Pre-fix the OR over
    // `parsed_module` did exactly that.
    let has_dispatcher_call = parsed_instance
        .as_ref()
        .is_some_and(|p| svn_analyze::has_event_dispatcher_call(&p.program));
    // Reviewer follow-up #3a: AST-based `$$Events` detection
    // replaces the substring scan that false-fired on comments and
    // string literals AND missed `type $$Events=…` (no trailing
    // whitespace before `=`) / `type $$Events<T>=…` (generic).
    // Computed once and threaded through to every gate that used to
    // call `has_strict_events_decl`.
    let has_strict_events_decl =
        svelte4::compat::has_strict_events_ast(parsed_instance.as_ref(), parsed_module.as_ref());
    // SlotHandler PLAN Stage 5: instance-script-only `$$Slots`
    // detection. When the user declared `interface $$Slots` or
    // `type $$Slots`, the render-fn return uses that as the slots
    // surface; the synthesised slot-defs are ignored.
    let has_strict_slots_decl = svelte4::compat::has_strict_slots_ast(parsed_instance.as_ref());
    let runes_mode = is_runes_mode(
        doc,
        fragment,
        parsed_instance.as_ref(),
        parsed_module.as_ref(),
    );
    let ambients = svn_analyze::find_ambient_refs(
        fragment,
        doc.source,
        parsed_instance.as_ref().map(|p| &p.program),
        parsed_module.as_ref().map(|p| &p.program),
    );

    // Single analyze-time resolution of every Props decision emit
    // makes downstream — type text, type root name, destructure
    // locals, and which of the four priority branches produced the
    // result. See PropsInfo in svn-analyze.
    //
    // process_instance_script_content consumes `type_root_name` to decide whether a
    // given `type`/`interface` declaration IS the Props annotation.
    // Props always hoists, even when its body references locals via
    // `typeof`, because consumers need the Props type visible at
    // module scope to get typed contextual flow. Non-Props types
    // that reference body-locals via `typeof` stay body-scoped so
    // `keyof typeof X` resolves against the real declaration rather
    // than the lossy declare-const stub.
    let raw_props_info: PropsInfo =
        if let (Some(s), Some(parsed)) = (doc.instance_script.as_ref(), parsed_instance.as_ref()) {
            PropsInfo::build(&parsed.program, s.content, runes_mode)
        } else {
            PropsInfo::default()
        };

    // TS-source hard-mode synthesis: when the overlay is TS AND the
    // source script is `<script lang="ts">` AND there's a `$props()`
    // destructure AND PropsInfo found no other type source (no TS
    // annotation / no $$Props / no export-let), synthesise a literal
    // `{ k: T, k?: U, … }` from the destructure and inject it as the
    // Props type source.
    //
    // Mirrors upstream svelte2tsx's `ExportedNames.handle$propsRune`
    // lines 286-399: TS files fall through the JSDoc-comment path
    // (`if (!this.isTsFile)` gate at line 240) and go straight to the
    // "best-effort" synthesis from the destructure object pattern.
    //
    // Rationale for the lang-gate: if we mirrored upstream exactly for
    // JS-source files too, we'd need to convert JSDoc `@typedef` Props
    // into a TS type alias, which is a bigger fix. For the BlockEditor
    // / SectionEditor-style `head` under-fire cluster — the
    // real-diagnostic gap on the CMS-style bench — only
    // TS-source components are load-bearing, so scope the change
    // narrowly and expand later if needed.
    // SvelteKit route files (+page.svelte / +layout.svelte /
    // +error.svelte) with an untyped `$props()` object destructure:
    // upstream's best-effort synthesis takes its route-aware branch and
    // types only the props SvelteKit passes (`data: PageData` etc.,
    // see `sveltekit::synthesize_route_props_type`). It runs for JS
    // components too, unless a leading `@type` comment already types
    // the declaration. The outer `Some` says the route branch applies;
    // an inner `None` means it produced no type and upstream leaves the
    // props `any`.
    //
    // For TS the result feeds `props_info.type_text`, so the
    // `$$ComponentProps` alias and the destructure annotation both
    // land. For JS it becomes the `@typedef` below and a JSDoc cast on
    // the `$props()` call types the destructured locals.
    let is_route_file = sveltekit::route_kind(source_path).is_some();
    let route_props_synth: Option<Option<String>> = sveltekit::route_kind(source_path)
        .filter(|_| {
            raw_props_info.props_rune
                && raw_props_info.props_object_pattern
                && raw_props_info.type_text.is_none()
                && (is_ts || !raw_props_info.props_type_comment)
        })
        .map(|kind| {
            let keys: Vec<&str> = raw_props_info
                .destructures
                .iter()
                .filter(|p| !p.is_rest && !p.local_only)
                .map(|p| p.prop_key.as_str())
                .collect();
            sveltekit::synthesize_route_props_type(kind, &keys, raw_props_info.props_with_unknown)
        });
    let route_props_override: Option<String> = match &route_props_synth {
        Some(Some(body)) if is_ts => Some(body.clone()),
        Some(Some(_)) => None,
        Some(None) => Some("any".to_string()),
        None => None,
    };
    let synth_override: Option<String> = route_props_override.or_else(|| {
        let synth = if is_ts
            && !is_route_file
            && raw_props_info.type_text.is_none()
            && (!raw_props_info.destructures.is_empty() || raw_props_info.props_with_unknown)
        {
            synthesise_js_props_typedef_body(&raw_props_info)
        } else {
            None
        };
        synth.or_else(|| {
            if route_props_synth.is_some() {
                return None;
            }
            // `let props = $props()` with nothing to name: upstream's
            // `$$ComponentProps` alias goes undeclared and the props
            // type is `any`.
            (raw_props_info.props_rune
                && raw_props_info.type_text.is_none()
                && !raw_props_info.props_with_unknown
                && raw_props_info
                    .destructures
                    .iter()
                    .all(|d| d.local_only || d.is_rest))
            .then(|| "any".to_string())
        })
    });
    // Two-step construction with no post-build mutation: emit-time
    // context (route kind, is_ts) decides whether to override the
    // analyze-derived type text, then PropsInfo is rebuilt via
    // struct-update with that decision applied. Architecture rule
    // #2: analyze outputs are read-only in emit.
    let props_info: PropsInfo = match synth_override {
        Some(literal) => PropsInfo {
            type_text: Some(literal),
            type_span: None,
            type_root_name: None,
            source: svn_analyze::PropsSource::SynthesisedFromDestructure,
            ..raw_props_info
        },
        None => raw_props_info,
    };

    // Gate for event-type narrowing, matching upstream svelte2tsx
    // (`ComponentEvents.hasStrictEvents` and `addComponentExport.ts`).
    // Narrow ONLY when the user opted in via ONE of:
    //   1. `interface $$Events` / `type $$Events` declared.
    //   2. `<script strictEvents>` attribute.
    //   3. Runes mode — but only on the generics export path, whose
    //      class wrapper is the one place upstream OR-s `isRunesMode()`
    //      into the strictness; the plain path stays lax.
    // Otherwise stay lax (child events flow through the default
    // `(e: any) => any` overload). This matches upstream's behavior
    // for Svelte-4 components that happen to use
    // `createEventDispatcher<T>()` without opting into strict events —
    // narrowing those without opt-in produced 18 legitimate-but-new
    // errors on a Svelte-4 bench in the reverted commit 3c24f18.
    let narrow_events =
        has_strict_events_decl || has_strict_events_attr(doc) || (runes_mode && generics.is_some());
    // If the component doesn't already declare `$$Events` but opted in
    // via one of the other two triggers, pull the dispatcher's type
    // argument as the source for a synthesised `type $$Events = T;`.
    // Returns None when the user doesn't use `createEventDispatcher<T>()`
    // or aliases the import — fall-through to the lax shim is safe in
    // both cases.
    // Reviewer follow-up #3: merge ALL typed dispatcher type args
    // AND untyped dispatched names into one combined detail map.
    // Pre-fix the typed path returned only the FIRST `<T>` and
    // `or_else` suppressed the untyped path whenever any typed
    // dispatcher existed; multi-dispatcher and mixed-typed-untyped
    // components silently lost event signatures.
    //
    // Mirrors upstream `ComponentEvents.toDefString()`:
    //   - typed dispatchers spread their `<T>` into the detail map
    //     (intersection in our shape)
    //   - untyped-only dispatchers' `dispatch('name', …)` names get
    //     `any` typing
    //
    // Final shape: `(T1) & (T2) & … & { untypedName: any, … }` where
    // each Ti is a typed dispatcher's type arg slice. Duplicate
    // names across typed Ts produce TS intersection of their
    // value types — surfaces conflicts deliberately. Names appearing
    // in BOTH a typed dispatcher and an untyped dispatcher fall to
    // `any` via the intersection (matches upstream's
    // `ComponentEvents.addEvent` "multiple definitions → any-typing"
    // behavior).
    // Reviewer follow-up #1 (round 4): drop the `narrow_events`
    // gate. Upstream svelte2tsx's `ComponentEvents` ALWAYS collects
    // typed dispatchers, untyped-dispatched names, and bubbled
    // events regardless of strict mode. The strict-vs-lax decision
    // applies AFTER collection: strict surfaces stay narrowed; lax
    // surfaces add `__sveltets_2_with_any_event` (an intersection
    // with `{ [evt: string]: CustomEvent<any> }`) so unknown event
    // names still pass without losing the per-name typed entries.
    //
    // Skip synth only when the user declared `interface $$Events`
    // (their declaration is authoritative). For every other case
    // — strict trigger or not — collect, then decide widening at
    // alias-body composition time.
    // Round-7 follow-up #5: keep typed-dispatcher and untyped-
    // dispatched halves separate at synthesis time. Upstream's
    // `toDefString` emits them at DIFFERENT positions in the events
    // object literal: typed dispatchers spread first, bubbles next,
    // untyped/duplicate-typed-collapse last. JS spread/object-key
    // semantics make the LAST occurrence of any key win, which is
    // why upstream's untyped names override bubbles which override
    // typed dispatchers. Pre-fix native folded both into one
    // intersection string and bubble overrode BOTH (round-6 #1) —
    // upstream's "untyped overrides bubble" wasn't captured.
    let (synthesized_typed_events, synthesized_untyped_events): (Option<String>, Option<String>) =
        if has_strict_events_decl {
            (None, None)
        } else {
            let typed_args: Vec<String> = parsed_instance
                .as_ref()
                .zip(doc.instance_script.as_ref())
                .map(|(p, s)| {
                    svn_analyze::find_dispatcher_event_type_sources(&p.program, s.content)
                })
                .unwrap_or_default();
            let mut untyped_names: Vec<String> = parsed_instance
                .as_ref()
                .map(|p| {
                    // Round-13 follow-up #1: source-order single-pass
                    // tracking — `find_dispatched_event_names` now
                    // discovers untyped-dispatcher locals INCREMENTALLY
                    // as it walks, so forward calls
                    // `dispatch('ready'); const dispatch = …`
                    // don't resolve. Pre-fix the helper called
                    // `find_untyped_dispatcher_local_names` first
                    // (whole-program collection) and then scanned
                    // calls — forward refs registered wrongly.
                    svn_analyze::find_dispatched_event_names(&p.program)
                })
                .unwrap_or_default();
            // Round-8 follow-up #5: collapse names duplicated across
            // multiple inline typed dispatchers to `CustomEvent<any>`.
            // Upstream's `addToEvents` (`ComponentEvents.ts:279`)
            // detects a name added twice and pushes it into
            // `dispatchedEvents`, which `toDefString` emits last as
            // `'name': customEvent` — overriding both spreads with
            // `CustomEvent<any>`. We use the same path: any inline-
            // type-literal member name that appears 2+ times across
            // typed dispatchers gets injected into `untyped_names`
            // (route they already take through the round-7 #5 layer
            // order, where untyped overrides typed and bubble).
            //
            // `{foo: A} & {foo: B}` (TS intersection of typed
            // sources, our pre-fix behaviour) collapsed to
            // `CustomEvent<A & B>` — typically `never` for unrelated
            // primitives, which TS rejects on every consumer call.
            // The post-fix override produces `CustomEvent<any>`,
            // which matches upstream and accepts every handler.
            if let Some(p) = parsed_instance.as_ref() {
                let all_inline_member_names =
                    svn_analyze::collect_inline_typed_dispatcher_member_names(&p.program);
                let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
                let mut already_in_untyped: std::collections::HashSet<String> =
                    untyped_names.iter().cloned().collect();
                for name in &all_inline_member_names {
                    if !seen.insert(name.clone()) && !already_in_untyped.contains(name) {
                        untyped_names.push(name.clone());
                        already_in_untyped.insert(name.clone());
                    }
                }
                // SVELTE-4-COMPAT: dispatcher-vs-bubble name collision.
                // When a component declares an explicit dispatcher event
                // AND bare-forwards an event of the same name from a
                // child component or DOM element, BOTH paths fire that
                // event on the parent. The consumer's `$on(name, h)`
                // handler receives EITHER payload, so the type at the
                // consumer site should be the union — but TypeScript
                // can't naturally union "the dispatcher type" with "an
                // arbitrary CustomEvent payload" without losing precision
                // on either side. Upstream svelte2tsx sidesteps this by
                // emitting a final `'name': __sveltets_2_customEvent`
                // (CustomEvent<any>) entry in the events object literal
                // — duplicate-key-last-wins makes the conflict resolve
                // to `CustomEvent<any>` for those names. Mirror that:
                // if a name appears in BOTH the inline-typed dispatcher
                // member list AND the bubbled event list, add it to
                // `untyped_names` so the layer-last override emits
                // `'name': CustomEvent<any>` here too. Without this the
                // `Omit<typed, keyof bubble> & bubble` shape lets bubble
                // win exclusively, dropping the dispatcher's payload
                // type — `<Parent on:menuOptionSelected={({detail}) =>
                // detail.folderId}>` then fails TS2339 because the
                // bubbled child's payload doesn't have `folderId`.
                let mut bubble_names: std::collections::HashSet<String> =
                    std::collections::HashSet::new();
                for ev in &summary.bubbled_dom_events {
                    bubble_names.insert(ev.name.to_string());
                }
                for ev in &summary.bubbled_component_events {
                    bubble_names.insert(ev.event_name.to_string());
                }
                for name in &all_inline_member_names {
                    if bubble_names.contains(name) && !already_in_untyped.contains(name) {
                        untyped_names.push(name.clone());
                        already_in_untyped.insert(name.clone());
                    }
                }
            }
            // Round-9 follow-up #2: model upstream's
            // `{...toEventTypings<T1>(), ...toEventTypings<T2>(), ...}`
            // value-spread at the TYPE level via chained
            // `Omit<prev, keyof Ti> & Ti`. Each later spread overrides
            // the previous spread's keys for the same name. Pre-fix
            // native intersected the sources as `(T1) & (T2)`, which
            // for shared keys with incompatible types collapses to
            // `T1 & T2` (e.g. `boolean & string` = `never`) — every
            // consumer handler then failed against `CustomEvent<never>`.
            // The new shape gives source-order-last-wins, matching
            // upstream's spread.
            //
            // Inline-literal duplicate handling (round-8 #5) still
            // applies: collisions detected at synth time also route
            // through the untyped-names layer, which the round-7 #5
            // layer order overrides last with `CustomEvent<any>`.
            // For type-aliased sources (where we can't enumerate keys
            // at synth time), the chained Omit handles overlap on its
            // own — `keyof Tj` is computed at type-check time and
            // produces the correct override.
            let typed = match typed_args.split_first() {
                None => None,
                Some((first, rest)) => {
                    let mut acc = format!("({first})");
                    for next in rest {
                        acc = format!("Omit<{acc}, keyof ({next})> & ({next})");
                    }
                    Some(acc)
                }
            };
            // Untyped dispatched names: each gets `CustomEvent<any>`
            // at the type level (mirrors upstream's
            // `__sveltets_2_customEvent` shim, declared as
            // `CustomEvent<any>`). Emitted at the LAST layer of the
            // events object, overriding any earlier typed/bubble
            // entry for the same name.
            let untyped = if untyped_names.is_empty() {
                None
            } else {
                let body = untyped_names
                    .iter()
                    .map(|n| format!("{n:?}: CustomEvent<any>"))
                    .collect::<Vec<_>>()
                    .join(", ");
                Some(format!("{{ {body} }}"))
            };
            (typed, untyped)
        };
    // Reviewer item #3c part 2: bare `<button on:click>` directives on
    // a DOM element forward the native DOM event to a parent listener.
    // At type-check time, the consumer's `<Child on:click={cb}>` should
    // see the DOM event shape (`MouseEvent`) rather than the lax
    // `CustomEvent<any>` fallback. Project each captured name into
    // `HTMLElementEventMap[NAME]` and intersect into the final
    // `$$Events` alias below.
    //
    // Reviewer follow-up #1 (round 4) removed the `narrow_events`
    // gate from this synth: bubbled DOM events are now collected
    // unconditionally and intersected into `events_alias_body`.
    // Non-strict mode still gets a usable surface because the
    // alias-composition step intersects with
    // `{ [evt: string]: CustomEvent<any> }` (mirrors upstream's
    // `__sveltets_2_with_any_event`) so unknown names still pass
    // while the bubbled-DOM names carry their proper DOM event
    // type. The only skip remaining: when the user declared
    // `interface $$Events`, their declaration is authoritative
    // and we don't synthesise.
    //
    // Dedup names — `<button on:click><img on:click />` would
    // otherwise emit two `"click"` keys in the projection. Keys in a
    // TS object type are unique; duplicates compile but produce noisy
    // diagnostics. Walk-order preserved for stable emit (snapshots).
    // Reviewer follow-up #1 (round 5): merge DOM and component
    // bubbles into ONE flat per-name map so cross-kind same-name
    // collisions resolve as overwrite/union (matching upstream's
    // single `EventHandler.bubbledEvents` map) rather than
    // intersecting two separate fragments.
    //
    // Round-6 follow-up #1: dispatcher fragments and the bubbled
    // event map are no longer intersected with `&`. Instead the
    // dispatcher mapped type and the bubble literal are combined as
    // `Omit<Dispatcher, keyof Bubble> & Bubble` — TS-level analogue
    // of upstream's value-position spread (`{...toEventTypings<T>(),
    // 'click': mapElementEvent('click')}`), where bubble keys
    // override dispatcher keys for same name and non-overlapping
    // keys keep both. See the `events_combined` block further down.
    //
    // Per-entry source tracks how each contribution renders:
    //   - Dom(scope)      → `<Map>[name]` for the given element scope.
    //   - Component(root) → `__SvnComponentEvents<typeof root>[name]`.
    //
    // The full per-name entry is an ordered `Vec<BubbleSource>` and
    // the final emit is the union of every projection in the list
    // (or just the single projection if only one source survives).
    //
    // Merge rules (positional source-order traversal) — mirror upstream
    // `event-handler.ts:18` (`set(name, expr)` for DOM) and
    // `event-handler.ts:55-60` (`[].concat(exist, exp)` for component
    // bubbles):
    //   - DOM source incoming for `name`       → REPLACE the entire
    //                                             entry with the new
    //                                             Dom source (matches
    //                                             upstream's `set()`,
    //                                             which drops any
    //                                             prior expression).
    //   - Component source incoming for `name` → APPEND to the entry
    //                                             so a prior DOM (or
    //                                             component) source
    //                                             unions with the new
    //                                             component root.
    //
    // Concretely:
    //   D, C  →  [D, C]   (component appends to DOM)
    //   C, D  →  [D]      (DOM replaces all prior)
    //   D, D' →  [D']     (later DOM replaces earlier DOM)
    //   C, C' →  [C, C']  (components accumulate)
    enum BubbleSource {
        Dom(svn_analyze::BubbledDomEventScope),
        Component(String),
    }
    let bubbled_event_map: Option<String> = if has_strict_events_decl
        || (summary.bubbled_dom_events.is_empty() && summary.bubbled_component_events.is_empty())
    {
        None
    } else {
        // Collect every bubble entry with its source position.
        // `(position, name, source)`.
        let mut all: Vec<(u32, &str, BubbleSource)> = Vec::with_capacity(
            summary.bubbled_dom_events.len() + summary.bubbled_component_events.len(),
        );
        for ev in &summary.bubbled_dom_events {
            all.push((ev.position, ev.name.as_str(), BubbleSource::Dom(ev.scope)));
        }
        for ev in &summary.bubbled_component_events {
            // Skip synthetic roots — `typeof __svn_self_default` /
            // `typeof (<expr>)` aren't well-formed `typeof`
            // expressions for arbitrary user code.
            let root = ev.component_root.as_str();
            if root == "__svn_self_default"
                || root.starts_with('(')
                || !root
                    .chars()
                    .next()
                    .is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
            {
                continue;
            }
            all.push((
                ev.position,
                ev.event_name.as_str(),
                BubbleSource::Component(root.to_string()),
            ));
        }
        all.sort_by_key(|(pos, _, _)| *pos);
        // Apply merge rules in position order.
        let mut entries: Vec<(&str, Vec<BubbleSource>)> = Vec::new();
        for (_, name, src) in all {
            let pos = entries.iter().position(|(n, _)| *n == name);
            match (pos, src) {
                (Some(idx), BubbleSource::Dom(scope)) => {
                    entries[idx].1 = vec![BubbleSource::Dom(scope)];
                }
                (Some(idx), BubbleSource::Component(root)) => {
                    let already_present = entries[idx].1.iter().any(
                        |s| matches!(s, BubbleSource::Component(existing) if existing == &root),
                    );
                    if !already_present {
                        entries[idx].1.push(BubbleSource::Component(root));
                    }
                }
                (None, src) => {
                    entries.push((name, vec![src]));
                }
            }
        }
        // Reviewer follow-up #7: upstream svelte2tsx's shim
        // (`svelte-shims.d.ts:185-190`) declares
        // `__sveltets_2_mapBodyEvent` returning `WindowEventMap[K]`
        // and `__sveltets_2_mapWindowEvent` returning
        // `HTMLBodyElementEventMap[K]`. The naming is upstream-
        // internal — looks swapped relative to the DOM API, but it's
        // the source of truth for parity.
        fn render_source(src: &BubbleSource, name: &str) -> String {
            match src {
                BubbleSource::Dom(scope) => {
                    let map_name = match scope {
                        svn_analyze::BubbledDomEventScope::Element => "HTMLElementEventMap",
                        svn_analyze::BubbledDomEventScope::SvelteBody => "WindowEventMap",
                        svn_analyze::BubbledDomEventScope::SvelteWindow => {
                            "HTMLBodyElementEventMap"
                        }
                    };
                    format!("{map_name}[{name:?}]")
                }
                BubbleSource::Component(root) => {
                    format!("__SvnComponentEvents<typeof {root}>[{name:?}]")
                }
            }
        }
        let mut body = String::new();
        for (i, (name, sources)) in entries.iter().enumerate() {
            if i > 0 {
                body.push_str(", ");
            }
            if sources.len() == 1 {
                let _ = write!(body, "{name:?}: {}", render_source(&sources[0], name));
            } else {
                let parts: Vec<String> = sources.iter().map(|s| render_source(s, name)).collect();
                let _ = write!(body, "{name:?}: ({})", parts.join(" | "));
            }
        }
        if body.is_empty() {
            None
        } else {
            Some(format!("{{ {body} }}"))
        }
    };

    // SVELTE-4-COMPAT: rewrite `$: ...` reactive statements before
    // the Svelte-5-shaped passes run, so downstream code sees the
    // Svelte-5 equivalents:
    //   - `$: b = expr`    → `let b = $derived(expr)` (declaration)
    //   - `$: count++`     → `count++;`                (re-assignment, label dropped)
    //   - `$: console.log` → `() => { $: console.log };` (expr/block wrap)
    // See crates/emit/src/svelte4/reactive.rs.
    let mut reactive_touched_names: Vec<SmolStr> = Vec::new();
    // Pre-compute whether we'll emit `type $$ComponentProps = {...}`
    // at module scope. The script-rewrite pipeline needs to know so
    // it can also annotate the `$props()` destructure with
    // `: $$ComponentProps`. Mirrors upstream svelte2tsx's two-part
    // emission (`ExportedNames.ts:380-389`): the module-scope alias
    // AND the destructure-site `: $$ComponentProps` BOTH land for
    // rename/find-references to work seamlessly and for the
    // destructure's `data`/`form`/etc. locals to pick up the
    // synthesized route type rather than `$props()`'s loose return.
    let will_emit_component_props_alias = is_ts
        && props_info
            .type_text
            .as_deref()
            .is_some_and(|t| t.trim_start().starts_with('{'))
        && matches!(
            props_info.source,
            svn_analyze::PropsSource::SynthesisedFromDestructure
                | svn_analyze::PropsSource::RuneAnnotation
                | svn_analyze::PropsSource::RuneGeneric
        );
    // SVELTE-4-COMPAT: when `type NAME = $$Generic[<args>];` declarations
    // synthesised the render-fn's generic param list (see
    // `synthesise_generics_from_dollar_generic`), blank those
    // declarations from the body. Otherwise the body's local
    // `type NAME = $$Generic = any` shadows the generic parameter and
    // tsgo fires TS2300 ("Duplicate identifier") on each one. Mirrors
    // upstream svelte2tsx's `Generics.ts` strip pass at
    // `language-tools/packages/svelte2tsx/src/svelte2tsx/nodes/Generics.ts`.
    // JS route component with a synthesised `$$ComponentProps`
    // typedef: the destructured locals read their types through a
    // JSDoc cast on the `$props()` call.
    let js_route_props_typed = !is_ts && matches!(route_props_synth, Some(Some(_)));
    let strip_dollar_generic = doc
        .instance_script
        .as_ref()
        .is_some_and(|s| s.generics.is_none())
        && generics.is_some();
    let rewritten_content: Option<String> = doc.instance_script.as_ref().map(|s| {
        let (after_reactive, touched) =
            svelte4::reactive::rewrite_with_touched_names(s.content, s.lang);
        reactive_touched_names = touched;
        let after_reactive = if strip_dollar_generic {
            blank_dollar_generic_decls(&after_reactive)
        } else {
            after_reactive
        };
        let after_state = after_reactive;
        // Reviewer follow-up #3b: when `interface $$Events` is
        // declared, rewrite untyped `createEventDispatcher()` calls
        // to `createEventDispatcher<__SvnCustomEvents<$$Events>>()`
        // so `dispatch('name', detail)` calls inside the component
        // type-check against $$Events. Mirrors upstream
        // `ComponentEvents.ts:130`.
        let after_state = if has_strict_events_decl {
            svelte2tsx_nodes::component_events::rewrite_dispatcher_typing(&after_state, s.lang)
        } else {
            after_state
        };
        // Inject `: $$ComponentProps` on the untyped `$props()`
        // destructure pattern when an alias was synthesized. Without
        // this, `const { data } = $props()` picks up `$props()`'s loose
        // return type (not our synthesized `{ data: PageData }`) and
        // downstream reads of `data.chartData` collapse to `any`,
        // breaking generic-component inference on consumers.
        if will_emit_component_props_alias {
            inject_component_props_annotation(&after_state, s.lang)
        } else if js_route_props_typed {
            inject_jsdoc_props_cast(&after_state, s.lang)
        } else {
            after_state
        }
    });
    // Identity rewrite chains collapse to None: split_imports falls
    // back to the original content, and the bindings reparse in
    // analyze_script_and_template_refs is skipped — re-parsing
    // identical bytes contributes nothing `parsed_instance` didn't.
    let rewritten_content = rewritten_content.filter(|rw| {
        doc.instance_script
            .as_ref()
            .is_some_and(|s| rw.as_str() != s.content)
    });

    // Hoist imports out of the instance script. Required because the
    // instance body gets wrapped in `function $$render() { ... }` and ES
    // `import` declarations can't appear inside a function (TS1232).
    let split = doc.instance_script.as_ref().map(|s| {
        let content = rewritten_content.as_deref().unwrap_or(s.content);
        split_imports(
            content,
            s.lang,
            generics.is_some(),
            props_info.type_root_name.as_deref(),
        )
    });

    hoisted_imports::emit_hoisted_imports(&mut buf, split.as_ref(), doc, is_ts);

    // `<script generics="T extends ...">` (extracted above) — expose
    // the type params as generics on the wrapping function so
    // references inside the body resolve. Falls back to no-generics
    // when the attribute is absent.
    //
    // The wrapper is `async` because Svelte 5 components are allowed to
    // use top-level `await` in their `<script>` body (TLA via Vite/SvelteKit
    // is supported); without `async` we'd report TS1308 for those.
    // For JS overlays, synthesise `@typedef {...} $$ComponentProps`
    // when the destructure has non-bindable keys that aren't in the
    // user's `@typedef Props` block — upstream svelte2tsx's
    // selector. Bindable-only extras (e.g. `element = $bindable()`)
    // don't trigger synthesis; upstream treats them as part of the
    // "real" props shape that Props may omit. When the user has
    // no Props at all, synthesis fires unconditionally.
    //
    // Per-default-value type inference in
    // `analyze::infer_default_type` mirrors upstream's
    // `getTypeForDefault` (`= ''` → `string`, `= () => {}` →
    // `Function`, `= {}` → `Record<string, any>`, `= null` → widen
    // to `any`, …) so the synthesised typedef matches upstream's
    // shape on the synth path.
    let synthesised_js_props_typedef = if let (false, Some(route)) = (is_ts, &route_props_synth) {
        route.clone()
    } else if !is_ts {
        let script = doc
            .instance_script
            .as_ref()
            .map(|s| s.content)
            .unwrap_or("");
        if should_synthesise_js_props(&props_info, script) {
            synthesise_js_props_typedef_body(&props_info)
        } else {
            None
        }
    } else {
        None
    };
    if let Some(body) = synthesised_js_props_typedef.as_deref() {
        // JSDoc `@typedef {<typespec>} Name` — body already includes
        // the outer `{}` for object-literal types, so the JSDoc
        // wrapping pair gives `{{...}}` in the final output.
        let typedef = format!("/** @typedef {{{body}}} $$ComponentProps */");
        // Upstream writes the typedef in front of the `$props()`
        // declarator, so an error inside it (a `$types` member the
        // route doesn't export) is reported at that point.
        match (props_info.props_decl_anchor, doc.instance_script.as_ref()) {
            (Some(anchor), Some(script)) => {
                let at = script.content_range.start + anchor;
                buf.append_with_source(&typedef, svn_core::Range::new(at, at + 1));
            }
            _ => buf.push_str(&typedef),
        }
        buf.push_str("\n");
    }

    // TS overlay: wrap inline-literal Props types in a module-scope
    // `type $$ComponentProps = …;` alias and swap the literal for the
    // alias name in downstream emit. Two cases feed this path:
    //
    //   1. `PropsSource::SynthesisedFromDestructure` — the TS-source
    //      hard-mode synthesis block above replaced `type_text` with
    //      a literal from the destructure shape.
    //   2. `PropsSource::RuneAnnotation` with a literal `{ … }`
    //      annotation on the `$props()` destructure — e.g.
    //      `let { site }: { site?: Site } = $props()`. Upstream
    //      svelte2tsx aliases these too (see their emit for
    //      SitePreview.svelte).
    //
    // Consumer error messages then reference `$$ComponentProps` as the
    // target type rather than the inlined literal structure — matches
    // upstream byte-for-byte on excess-prop errors.
    let ty_is_literal = props_info
        .type_text
        .as_deref()
        .is_some_and(|t| t.trim_start().starts_with('{'));
    let should_alias = is_ts
        && ty_is_literal
        && matches!(
            props_info.source,
            svn_analyze::PropsSource::SynthesisedFromDestructure
                | svn_analyze::PropsSource::RuneAnnotation
                | svn_analyze::PropsSource::RuneGeneric
        );
    // Alias placement: ALWAYS body-local when emitting `type
    // $$ComponentProps = …`. Two reasons body-scope is the right home:
    //
    //   1. Generics. `<script generics="T">` declares `T` as the
    //      render fn's binder — at module scope `type $$ComponentProps
    //      = { x: T }` fires TS2304.
    //   2. Body-local type aliases. A user-declared `type Foo = …`
    //      stays body-scoped; if the props annotation references
    //      `Foo` (e.g. `state: Foo | undefined`), a module-scope
    //      `$$ComponentProps` referencing `Foo` either fires TS2304
    //      or — worse — silently resolves to `unknown` and TS6133
    //      fires on the body-local `Foo` for being "unused".
    //
    // Body-local placement keeps the alias in scope of every name the
    // user might reference. The destructure annotation
    // `: $$ComponentProps` is INSIDE the body too, so it resolves
    // cleanly. Mirrors upstream svelte2tsx's `ts-runes-bindable.v5` /
    // `ts-runes-best-effort-types.v5` shape (always body-scoped).
    let alias_body = if should_alias {
        props_info.type_text.clone()
    } else {
        None
    };
    // After the alias decision, downstream code reads the EFFECTIVE
    // type text — either `$$ComponentProps` (when aliased) or the
    // original `props_info.type_text`. Carrying these as locals keeps
    // `props_info` itself immutable for the rest of emit, matching
    // architecture rule #2's "analyze outputs are read-only".
    let effective_props_type_text: Option<String> = if alias_body.is_some() {
        Some("$$ComponentProps".to_string())
    } else {
        props_info.type_text.clone()
    };

    // The render-fn signature is synthesized whole, but it is not
    // invisible to the type checker: it is where the component's props
    // type surfaces, so a diagnostic about that type lands here rather
    // than on anything the user typed. Under `declaration: true` the
    // canonical case is TS4060 — a `generics="T">`-parameterised
    // component whose props interface closes over `T` without declaring
    // it, making the interface a function-local name the declaration
    // writer cannot reference from module scope.
    //
    // Anchor the whole signature to the `<script>` tag's opening so
    // those diagnostics keep a real source position instead of being
    // dropped as unmapped scaffolding. The source span is the single
    // byte after `<`, and the mapper clamps every overlay offset within
    // the header into it, so any column on this line reports at the tag
    // name. That is the position upstream lands on too: its source map
    // carries a mapping at the head of this same generated line and
    // nothing after it, so an unmapped column there resolves backwards
    // to the tag.
    let header_start = buf.as_str().len() as u32;
    // The render function is `async` only when the script awaits at
    // its root scope (upstream `hasTopLevelAwait`): an `await` inside a
    // block or a function does not count, and then TypeScript reports
    // it (TS1308) the way upstream does.
    let render_async = if parsed_instance
        .as_ref()
        .is_some_and(|p| svn_analyze::has_root_scope_await(&p.program))
    {
        "async "
    } else {
        ""
    };
    // Root `{#snippet}` blocks are hoisted out of the template
    // (upstream `index.ts`, `rootSnippets`): to module scope when
    // every free name they reference is allowed there — nothing the
    // instance script declares — otherwise to the render function's
    // start, ahead of the script body.
    let root_snippets: Vec<&svn_parser::SnippetBlock> = fragment
        .nodes
        .iter()
        .filter_map(|n| match n {
            Node::SnippetBlock(b) => Some(b.as_ref()),
            _ => None,
        })
        .collect();
    let module_hoisted: Vec<bool> = module_hoistable_snippets(
        &root_snippets,
        doc,
        parsed_instance.as_ref(),
        parsed_module.as_ref(),
    );
    let instantiations = render_function::instantiation_index(summary);
    let mut snippet_action_counter: usize = 0;
    for (snippet, hoist) in root_snippets.iter().zip(&module_hoisted) {
        if *hoist {
            crate::nodes::snippet_block::emit_snippet_const(
                &mut buf,
                doc.source,
                snippet,
                0,
                &instantiations,
                &mut snippet_action_counter,
            );
        }
    }
    match &generics_with_origin {
        // A `$$Generic`-synthesised parameter list is scaffolding: the
        // user wrote `type T = $$Generic;` in the body, never a `<T>`
        // here. TS would otherwise report the parameter as unused at
        // this position, pointing at text that doesn't exist in the
        // source. Fencing it off suppresses that class the same way
        // upstream does (`Generics.toDefinitionString(true)` wraps the
        // list in its own ignore comments for exactly this path, while
        // an attribute-sourced list is left bare).
        Some((g, util::GenericsOrigin::DollarGeneric)) => {
            let _ = writeln!(
                buf,
                "{render_async}function {render_name}/*svn:ignore_start*/<{g}>/*svn:ignore_end*/() {{"
            );
        }
        Some((g, util::GenericsOrigin::Attribute)) => {
            let _ = writeln!(buf, "{render_async}function {render_name}<{g}>() {{");
        }
        None => {
            let _ = writeln!(buf, "{render_async}function {render_name}() {{");
        }
    }
    if let Some(script) = doc.instance_script.as_ref() {
        let tag_start = script.open_tag_range.start;
        buf.push_token_map(TokenMapEntry {
            overlay_byte_start: header_start,
            overlay_byte_end: buf.as_str().len() as u32,
            source_byte_start: tag_start.saturating_add(1),
            source_byte_end: tag_start.saturating_add(2),
        });
    }
    // Generic-scoped alias emission — see the `alias_body` decision above.
    // Lives at the very top of the render body so the destructure
    // annotation rewrite (`: $$ComponentProps`) downstream can reference
    // it. The `T` in `<script generics="T">` is the render fn's binder
    // and is in scope here.
    // Reviewer follow-up #1: same TS-only gate as `type $$Events`
    // below — JS overlays can't carry TS-only `type X = …`
    // declarations. The JS render-fn return short-circuits and
    // doesn't reference `$$ComponentProps`; the JS default export
    // gets its Props through `Awaited<ReturnType<typeof
    // $$render>>['props']` which already projects the destructure's
    // declared type. Skipping the alias on JS is safe.
    if is_ts && let Some(body) = alias_body.as_deref() {
        buf.push_str("    type $$ComponentProps = ");
        // The user's own annotation or type argument moved here, as
        // upstream moves it: its bytes keep their source positions.
        match (props_info.type_span, doc.instance_script.as_ref()) {
            (Some((start, end)), Some(script)) => {
                let base = script.content_range.start;
                buf.append_with_source(body, svn_core::Range::new(base + start, base + end));
            }
            _ => buf.push_str(body),
        }
        buf.push_str(";\n");
    }
    // Synthesised `type $$Events = { [K in keyof <T>]:
    // CustomEvent<<T>[K]> };` from a typed
    // `createEventDispatcher<T>()` call. The dispatcher's `T` is the
    // DETAIL map (`dispatch('foo', detail)` => `CustomEvent<detail>`),
    // so we wrap once HERE to produce the FINAL `$on` event-object
    // map. Downstream emit (render-fn return, `__svn_events`
    // marker, `__svn_ensure_component`) all treat `$$Events` as
    // final and never wrap again — keeping every consumer path at
    // exactly one wrap level. Mirrors upstream's
    // `__sveltets_2_CustomEvents<$$Events>` cast applied at the
    // dispatcher site.
    //
    // Placed INSIDE the render body so `T` can reference body-local
    // generics (`<script generics="A"> … createEventDispatcher<{a: A}>()`)
    // — at module scope `A` would fire TS2304. The class-wrapper's
    // `events()` method projects this back out to consumers via
    // `Awaited<ReturnType<typeof $$render<…>>>['events']`.
    // Final `$$Events` body. Combines two synthesised halves:
    //   1. `synthesized_events_type` is the dispatcher DETAIL map (`T`
    //      from `createEventDispatcher<T>()`, or `{ name: any, … }`
    //      from an untyped dispatcher's `dispatch('name', …)` calls).
    //      Wrapped once HERE into the FINAL `$on` event-object map:
    //      `{ [K in keyof T]: CustomEvent<T[K]> }`.
    //   2. `bubbled_event_map` is already the FINAL form
    //      (`{ "click": HTMLElementEventMap["click"], … }`) projected
    //      from bare `<elem|Comp on:NAME>` directives. DOM events are
    //      NOT wrapped in `CustomEvent` — they're the native event
    //      shape; component-bubbled events project through
    //      `__SvnComponentEvents<…>[NAME]`.
    //
    // Round-7 follow-up #5: layer the three event sources in
    // upstream's `toDefString` order. Each subsequent layer overrides
    // the keys of the previous via `Omit<prev, keyof curr> & curr` —
    // the type-level analogue of upstream's value-position spread:
    //
    //   typed dispatcher spreads  (= `...toEventTypings<T>()`)
    //   bubble entries            (= `'click': mapElementEvent(…)`)
    //   untyped dispatched names  (= `'foo': customEvent`)
    //
    // Round-6 follow-up #1 only handled (typed + bubble); pre-round-7
    // had bubble overriding ALL dispatcher keys, including untyped
    // names. Upstream emits untyped names AFTER bubbles, so untyped
    // wins.
    //
    // Round-8 follow-up #5 handles the duplicate-typed-name collapse
    // for INLINE type literals: keys appearing 2+ times across inline
    // typed dispatchers are pushed into `untyped_names` upstream of
    // this combine block, where the layered override resolves them as
    // `CustomEvent<any>` (matching upstream's `addToEvents` collision
    // override → `'name': customEvent` last in `toDefString`).
    fn wrap_typed_to_mapped(t: &str) -> String {
        format!("{{ [__svn_K in keyof ({t})]: CustomEvent<({t})[__svn_K]> }}")
    }
    fn override_layer(prev: &str, curr: &str) -> String {
        format!("Omit<{prev}, keyof ({curr})> & ({curr})")
    }
    let events_combined: Option<String> = {
        let typed_mapped = synthesized_typed_events
            .as_deref()
            .map(wrap_typed_to_mapped);
        // Layer in: bubble overrides typed.
        let after_bubble = match (typed_mapped.as_deref(), bubbled_event_map.as_deref()) {
            (Some(t), Some(b)) => Some(override_layer(t, b)),
            (Some(t), None) => Some(t.to_string()),
            (None, Some(b)) => Some(format!("({b})")),
            (None, None) => None,
        };
        // Layer in: untyped overrides everything.
        match (
            after_bubble.as_deref(),
            synthesized_untyped_events.as_deref(),
        ) {
            (Some(prev), Some(u)) => Some(override_layer(prev, u)),
            (Some(prev), None) => Some(prev.to_string()),
            (None, Some(u)) => Some(format!("({u})")),
            (None, None) => None,
        }
    };
    // Reviewer follow-up #1 (round 4): for NON-strict mode,
    // intersect the collected events with the lax index signature
    // `{ [evt: string]: CustomEvent<any> }` so unknown event names
    // still pass through. Mirrors upstream
    // `__sveltets_2_with_any_event` in
    // `svelte-shims.d.ts:243-246`: the events surface keeps each
    // typed entry AND admits arbitrary-string lookups. Strict mode
    // gets just the collected surface — no widening — so
    // `on:NAME` for unknown names fails the typed-keys constraint.
    //
    // `has_strict_events_decl` (interface case) skips this whole
    // block — `$$Events` resolves to the user's declaration at
    // module scope, no body-local synth needed.
    let lax_index_signature = "{ [evt: string]: CustomEvent<any> }";
    let events_alias_body: Option<String> = if let Some(collected) = events_combined.as_deref() {
        if narrow_events {
            Some(format!("({collected})"))
        } else {
            Some(format!("({collected}) & {lax_index_signature}"))
        }
    } else if narrow_events && !has_strict_events_decl {
        // Strict trigger active but no events synth'd — emit the
        // empty surface `type $$Events = {}`. Mirrors upstream
        // `_events(strictEvents=true, …)` in
        // `addComponentExport.ts:416-418`: drops the
        // `with_any_event` wrapper unconditionally on strict mode —
        // even with no declared events — so consumers' `on:NAME`
        // for any unknown name fails the empty `keyof $$Events`
        // constraint.
        Some("{}".to_string())
    } else {
        // Non-strict + no events synth'd: leave alias unset; the
        // events_field gate falls through to the lax `{ [evt:
        // string]: CustomEvent<any> }` shape directly (saves an
        // unnecessary alias declaration).
        None
    };
    // Reviewer follow-up #1: gate the `type $$Events = …` alias on
    // TS-only emission. JS overlays (`.svelte.svn.js`) can't carry
    // TS-only `type X = …` syntax — pure-JS parsers reject it, and
    // even tsgo's `allowJs` mode flags it as syntactically invalid
    // when `checkJs` is on. The JS render-fn's events field is
    // therefore always the lax `{ [evt: string]: CustomEvent<any> }`
    // index signature (JSDoc-cast), never a reference to this alias,
    // and the JS default export (`Component<Props, Exports>`) has no
    // events channel to feed either. Skip on JS; strict event
    // narrowing for JS overlays is a separate (larger) port that
    // requires JSDoc-friendly equivalents of the mapped/conditional
    // types this alias produces.
    if is_ts && let Some(body) = events_alias_body.as_deref() {
        let _ = writeln!(buf, "    type $$Events = {body};");
    }
    let ScriptAndTemplateAnalysis {
        bindable_prop_names,
        prop_type_source,
        store_refs,
    } = analyze_script_and_template_refs(
        doc,
        fragment,
        parsed_instance.as_ref(),
        split.as_ref(),
        rewritten_content.as_deref(),
        &props_info,
        effective_props_type_text.as_deref(),
    );

    // Stores that come from imports are declared at the start of the
    // render function (upstream `ImplicitStoreValues
    // .attachStoreValueDeclarationOfImportsToRenderFn`); the rest are
    // attached to their own declarations once the script body is in
    // the buffer.
    let mut store_bases: Vec<SmolStr> = store_refs
        .iter()
        .map(|name| SmolStr::from(name.strip_prefix('$').unwrap_or(name)))
        .collect();
    {
        let mut import_names: std::collections::HashSet<SmolStr> = std::collections::HashSet::new();
        if let Some(p) = parsed_instance.as_ref() {
            store_subscriptions::import_local_names(&p.program, &mut import_names);
        }
        if let Some(p) = parsed_module.as_ref() {
            store_subscriptions::import_local_names(&p.program, &mut import_names);
        }
        let imported: Vec<&str> = store_bases
            .iter()
            .filter(|b| import_names.contains(*b))
            .map(SmolStr::as_str)
            .collect();
        if !imported.is_empty() {
            let _ = writeln!(
                buf,
                "    {}",
                store_subscriptions::store_declarations(imported.iter().copied())
            );
            store_bases.retain(|b| !import_names.contains(b));
        }
    }

    // SVELTE-4-COMPAT: `$$slots`, `$$props`, `$$restProps` ambients.
    // Only inject the declaration when the source actually references
    // the name — keeps the overlay tight on Svelte-5-only codebases
    // and avoids shadowing the user's own `$$slots` local if any.
    // Detection is a substring check against the full document source
    // (script + template). Ambiguity risk: a literal `$$slots` inside
    // a string or comment would trigger the declaration, but that's
    // harmless — the `let` just goes unused in the overlay.
    emit_svelte4_ambients(buf.raw_string_mut(), ambients, is_ts);

    // Root snippets that stay in the component land here, at the
    // render function's start — before the script body, as upstream
    // moves them to `renderFunctionStart`. A closure in the snippet
    // therefore precedes the declarations it captures, and sees their
    // declared types rather than an initializer-narrowed one.
    for (snippet, hoist) in root_snippets.iter().zip(&module_hoisted) {
        if !*hoist {
            crate::nodes::snippet_block::emit_snippet_const(
                &mut buf,
                doc.source,
                snippet,
                1,
                &instantiations,
                &mut snippet_action_counter,
            );
        }
    }
    buf.resync_current_line();

    let mut instance_body: Option<std::ops::Range<usize>> = None;
    if let Some(s) = &split {
        if let Some(instance) = &doc.instance_script {
            // Resync the buffer's internal line counter — `emit_svelte4_ambients`
            // above uses `buf.raw_string_mut()` and pushes content without
            // updating `overlay_line`. `append_verbatim` relies on that
            // counter for LineMapEntry.overlay_start_line, so refresh it
            // before calling. Once those helpers take EmitBuffer directly
            // (later phases), this resync can go.
            buf.resync_current_line();
            // Same padding trick as the module-script site: pad a missing
            // trailing `\n` so `append_verbatim`'s LineMapEntry covers
            // the same overlay span `count_lines(&s.body)` accounted for.
            // `s.body` is the script-split output (imports removed), not
            // a slice of `doc.source`; the mapping from overlay → source
            // lines is an approximation starting at the original script's
            // `content_range.start` — same approximation the old manual
            // push was making.
            let padded;
            let text: &str = if s.body.ends_with('\n') {
                &s.body
            } else {
                padded = format!("{}\n", s.body);
                &padded
            };
            // R-Conv #2 (generalised): push byte-precise 1:1
            // TokenMapEntries for the parts of the body that are
            // byte-identical to the source slice. Without a token
            // entry, position translation falls back to the line map,
            // which returns the overlay COLUMN unchanged — wrong for
            // single-line scripts (`<script lang="ts">const asd:
            // string = true;</script>` sits at source col 18, not 0)
            // and wrong to the RIGHT of any in-line rewrite on the
            // same line (the `$state<T>(null)` generic injection,
            // dispatcher typing, `$props()` annotation, `$:` reactive
            // rewrite — all shift later columns).
            //
            // The body may differ from the source slice because of
            // those rewrites plus import-hoist blanking; none of them
            // add or remove newlines (the line map depends on that —
            // see the rewrite-invariants test module), but byte
            // offsets after a change point shift. Map the longest
            // common prefix and the longest common suffix as two 1:1
            // entries: everything before the first change and after
            // the last change keeps exact column mapping, and only
            // the changed middle falls back to the line-map
            // approximation.
            let body_no_pad = s.body.trim_end_matches('\n');
            if let Some(src_slice) = doc
                .source
                .get(instance.content_range.start as usize..instance.content_range.end as usize)
            {
                let src = src_slice.trim_end_matches('\n');
                let overlay_start = buf.raw_string_mut().len() as u32;
                for (overlay_off, src_off, len) in
                    aligned_spans(src.as_bytes(), body_no_pad.as_bytes())
                {
                    buf.push_token_map(TokenMapEntry {
                        overlay_byte_start: overlay_start + overlay_off,
                        overlay_byte_end: overlay_start + overlay_off + len,
                        source_byte_start: instance.content_range.start + src_off,
                        source_byte_end: instance.content_range.start + src_off + len,
                    });
                }
            }
            let body_start = buf.raw_string_mut().len();
            buf.append_verbatim(text, doc.source, instance.content_range);
            instance_body = Some(body_start..body_start + text.len());
        }
    }

    script_body_rewrites::apply_script_body_rewrites(
        &mut buf,
        split.as_ref().zip(instance_body),
        module_body,
        store_bases,
        &reactive_touched_names,
        source_path,
    );

    // Emit the template-check function for both TS and JS overlays.
    // TS-only syntax sites inside (bind: casts, typed lets, each-block
    // `i: number = 0`) are conditionalized on `is_ts` by the
    // sub-emitters; JS overlays get JSDoc equivalents or plain lets.
    emit_template_check_fn(
        &mut buf,
        doc,
        fragment,
        summary,
        is_ts,
        has_strict_slots_decl,
        !root_snippets.is_empty(),
    );

    let exported_locals: Vec<SmolStr> = split
        .as_ref()
        .map(|s| s.exported_locals.clone())
        .unwrap_or_default();

    let exports_object = build_exports_object(
        split.as_ref(),
        runes_mode,
        props_emit::uses_accessors(fragment, doc.source),
    );
    emit_void_block(
        buf.raw_string_mut(),
        summary,
        &bindable_prop_names,
        &exported_locals,
    );

    let export_type_infos = split
        .as_ref()
        .map(|s| s.export_type_infos.as_slice())
        .unwrap_or(&[]);
    // Locate the `interface $$Props` name span (in absolute source
    // bytes) so emit can anchor the synthesized
    // `__svn_ensure_right_props<…>(__svn_any("") as $$Props)` cast to
    // it. Upstream's LS does the same remap in
    // `DiagnosticsProvider.movePropsErrorRangeBackIfNecessary` —
    // a TS2345 fired in synthesized return-statement bytes resolves
    // onto the user-source interface declaration name.
    let dollar_props_name_range: Option<svn_core::Range> = doc
        .instance_script
        .as_ref()
        .zip(parsed_instance.as_ref())
        .and_then(|(s, p)| {
            for stmt in &p.program.body {
                if let oxc_ast::ast::Statement::TSInterfaceDeclaration(iface) = stmt
                    && iface.id.name == "$$Props"
                {
                    let span = iface.id.span;
                    let base = s.content_range.start;
                    return Some(svn_core::Range::new(base + span.start, base + span.end));
                }
            }
            None
        });
    emit_render_body_return(
        &mut buf,
        doc,
        generics.as_deref(),
        prop_type_source.as_deref(),
        events_alias_body.as_deref(),
        exports_object.as_deref(),
        export_type_infos,
        dollar_props_name_range,
        &props_info,
        synthesised_js_props_typedef.is_some(),
        &summary.slot_defs,
        has_strict_events_decl,
        has_strict_slots_decl,
    );

    buf.push_str("}\n");
    let _ = writeln!(buf, "{render_name};");

    // When the template forwards events from a sub-component via the
    // bare `on:EVENT` bubble shorthand (no `={…}` value), upstream's
    // `event-handler.ts` emits
    // `__sveltets_2_bubbleEventDef(__sveltets_2_instanceOf(<Child>).$$events_def, '<event>')`
    // for each bubble. The resulting events literal contains a circular
    // `typeof import('./Child.svelte')` reference that defeats generic
    // inference in `__sveltets_2_with_any_event`, collapsing Props to
    // its `{}` default. The downstream `__sveltets_2_isomorphic_component`
    // inherits that, and `__sveltets_2_ensureComponent(child)` returns
    // a ctor with `props?: {}` — no TS2353/TS2322 on consumer calls.
    //
    // We mirror this by widening the default-export's Props type to
    // `Record<string, any>` when the summary saw any bubble directive.
    // Closes the TS2322 over-fires at component-instantiation
    // sites that pass-through a parent's `page`/`page_slug` to a
    // child that forwards events via `on:delete` / `on:create`
    // (the recursive SitePages/Item pattern that surfaced the
    // need for this widening).
    let prop_type_effective: Option<String> = if summary.has_bubbled_component_event {
        Some("Record<string, any>".to_string())
    } else {
        prop_type_source.clone()
    };
    if is_ts {
        let has_bubbled_events =
            !summary.bubbled_dom_events.is_empty() || summary.has_bubbled_component_event;
        // Round-7 follow-up #6 / Round-8 follow-up #4: the fn-shape
        // gate cares about CONCRETE events from the dispatcher path
        // — entries that upstream's `events.size > 0` would count.
        // Two dispatcher sources contribute concrete entries:
        //
        //   - typed dispatcher with INLINE type literal members
        //     (`createEventDispatcher<{foo: string}>()`). The literal
        //     members enumerate at parse time so upstream's
        //     `dispatcherTyping.members.filter(...).forEach(addToEvents)`
        //     fires per member. A type-REFERENCE arg
        //     (`createEventDispatcher<MyEventMap>()`) does NOT —
        //     upstream stores the ref for `toDefString` spread but
        //     doesn't enumerate keys, so events.size stays 0.
        //
        //   - untyped dispatcher with string-literal `dispatch('name',
        //     …)` calls (covered by `find_dispatched_event_names` ⇒
        //     `untyped_names` ⇒ `synthesized_untyped_events`).
        //
        // Round-7 #6 used `synthesized_events_type.is_some()` which
        // OR'd typed-ANY (including type refs) and untyped — it
        // wrongly disqualified runes components that only had a
        // type-ref typed dispatcher. Compute the inline-literal
        // signal separately via `has_inline_typed_dispatcher_members`
        // and use the precise OR.
        let has_inline_typed_members = parsed_instance
            .as_ref()
            .is_some_and(|p| svn_analyze::has_inline_typed_dispatcher_members(&p.program));
        let has_concrete_dispatcher_events =
            has_inline_typed_members || synthesized_untyped_events.is_some();
        emit_default_export_declarations_ts(
            &mut buf,
            fragment,
            doc.source,
            &render_name,
            generics.as_deref(),
            prop_type_effective.as_deref(),
            has_dispatcher_call,
            has_concrete_dispatcher_events,
            events_alias_body.is_some(),
            has_strict_events_decl,
            has_bubbled_events,
            runes_mode,
            ambients,
        );
    } else {
        emit_default_export_declarations_js(
            &mut buf,
            &render_name,
            svelte4::compat::fragment_contains_default_slot(fragment, doc.source),
        );
    }

    // `.svelte` import specifiers are left unchanged. TS resolves
    // them via `allowArbitraryExtensions` + the ambient
    // `Foo.d.svelte.ts` sidecar written by the typecheck cache writer,
    // which re-exports from the real overlay at `Foo.svelte.svn.ts`.
    //
    // Not rewriting also preserves the bundler-mode auto-append path
    // for `import X from './Foo.svelte'` where `Foo.svelte.ts` is the
    // user's runes module (Svelte 5 convention, e.g. bits-ui,
    // shadcn-svelte) — TS tries `.svelte` literal, then `.svelte.ts`,
    // then our ambient, in that order. Rewriting to
    // `./Foo.svelte.svn.ts` would short-circuit the runes-module
    // fallback.

    let (out, line_map, token_map) = buf.finish();
    let overlay_line_starts = compute_line_starts(&out);
    let source_line_starts = compute_line_starts(doc.source);

    // All TokenMapEntries are now pushed inline during emit via
    // `EmitBuffer::append_with_source` (user-authored expression
    // splices) and `EmitBuffer::push_token_map` (synthesized-scaffolding
    // spans like component calls). No post-walk scanners remain.

    EmitOutput {
        typescript: out,
        render_name,
        line_map,
        token_map,
        overlay_line_starts,
        source_line_starts,
    }
}

use script_template_analysis::{ScriptAndTemplateAnalysis, analyze_script_and_template_refs};

/// Forward-declare top-level `{#snippet NAME(...)}` names at
/// `$$render_<hash>` function-body scope so the script body can
/// reference them. Mirrors upstream svelte2tsx's `hoistSnippetBlock`
/// (`SnippetBlock.ts:189-216`), which moves snippet blocks before the
/// script body so `let x = NAME;` in `<script>` resolves.
///
/// The hoist binds NAME to `any` (no arrow with params) — the
/// inner-scope hoist inside the template-check IIFE is what carries
/// the actual `(params) => null` signature for downstream `{@render}`
/// type checks. Using a bare `any` here avoids re-emitting the user's
/// param list at this site, which would duplicate `noImplicitAny`
/// diagnostics on each user param across overlay scopes.
/// Byte-identical spans between a source slice and the (possibly
/// rewritten) script body spliced into the overlay, aligned line by
/// line. Every script rewrite keeps the line count (the
/// rewrite-invariants tests hold them to it), so line `i` of the body
/// is line `i` of the source; within a line the common prefix and
/// suffix map first, and the changed middle is aligned on its longest
/// common substrings, recursively. A `$:` statement wrapped as
/// `;() => { … };` thus keeps exact columns for everything inside the
/// braces, as do the parts of a declaration the reactive rewrite
/// copied verbatim.
///
/// Falls back to whole-body prefix/suffix alignment when the line
/// counts differ.
fn aligned_spans(src: &[u8], body: &[u8]) -> Vec<(u32, u32, u32)> {
    let src_lines: Vec<&[u8]> = src.split(|&b| b == b'\n').collect();
    let body_lines: Vec<&[u8]> = body.split(|&b| b == b'\n').collect();
    if src_lines.len() != body_lines.len() {
        return common_affix_spans(src, body);
    }
    let mut spans = Vec::new();
    let (mut src_off, mut body_off) = (0u32, 0u32);
    for (s_line, b_line) in src_lines.iter().zip(body_lines.iter()) {
        align_line(s_line, b_line, src_off, body_off, &mut spans);
        src_off += s_line.len() as u32 + 1;
        body_off += b_line.len() as u32 + 1;
    }
    spans
}

/// Longest common substring of `a` and `b`, as `(a_start, b_start,
/// len)`, at least `min_len` bytes long and on char boundaries at both
/// ends. `None` when there is no such substring, or when the inputs
/// are too long for the quadratic search.
fn longest_common_substring(a: &[u8], b: &[u8], min_len: usize) -> Option<(usize, usize, usize)> {
    if a.is_empty() || b.is_empty() || a.len() * b.len() > 4_000_000 {
        return None;
    }
    let mut prev = vec![0u32; b.len() + 1];
    let mut cur = vec![0u32; b.len() + 1];
    let mut best: Option<(usize, usize, usize)> = None;
    for (i, &ca) in a.iter().enumerate() {
        for (j, &cb) in b.iter().enumerate() {
            cur[j + 1] = if ca == cb { prev[j] + 1 } else { 0 };
            let len = cur[j + 1] as usize;
            if len >= min_len && best.is_none_or(|(_, _, l)| len > l) {
                best = Some((i + 1 - len, j + 1 - len, len));
            }
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    let (mut a0, mut b0, mut len) = best?;
    // Trim to char boundaries: a run may start or end inside a
    // multi-byte char that only partly matches.
    while len > 0 && (a[a0] & 0xC0) == 0x80 {
        a0 += 1;
        b0 += 1;
        len -= 1;
    }
    while len > 0 && a0 + len < a.len() && (a[a0 + len] & 0xC0) == 0x80 {
        len -= 1;
    }
    (len >= min_len).then_some((a0, b0, len))
}

/// Align one source line with its overlay line: common prefix and
/// suffix first, then the longest common substring of what is left,
/// recursing into the pieces on either side of it.
fn align_line(
    src: &[u8],
    body: &[u8],
    src_off: u32,
    body_off: u32,
    spans: &mut Vec<(u32, u32, u32)>,
) {
    if src.is_empty() || body.is_empty() {
        return;
    }
    if src == body {
        spans.push((body_off, src_off, src.len() as u32));
        return;
    }
    let affix = common_affix_spans(src, body);
    let mut prefix = 0usize;
    let mut suffix = 0usize;
    for &(b, s, len) in &affix {
        spans.push((body_off + b, src_off + s, len));
        if b == 0 && s == 0 {
            prefix = len as usize;
        } else {
            suffix = len as usize;
        }
    }
    let src_mid = &src[prefix..src.len() - suffix];
    let body_mid = &body[prefix..body.len() - suffix];
    if let Some((a0, b0, len)) = longest_common_substring(src_mid, body_mid, 3) {
        let (s_base, b_base) = (src_off + prefix as u32, body_off + prefix as u32);
        align_line(&src_mid[..a0], &body_mid[..b0], s_base, b_base, spans);
        spans.push((b_base + b0 as u32, s_base + a0 as u32, len as u32));
        align_line(
            &src_mid[a0 + len..],
            &body_mid[b0 + len..],
            s_base + (a0 + len) as u32,
            b_base + (b0 + len) as u32,
            spans,
        );
    }
}

/// Longest-common-prefix and longest-common-suffix spans between a
/// source slice and the (possibly rewritten) script body spliced into
/// the overlay. Returns up to two `(overlay_offset, source_offset,
/// len)` spans over byte-identical content — the caller turns them
/// into 1:1 [`TokenMapEntry`]s so diagnostics inside keep exact
/// column mapping even when an in-line rewrite shifted bytes
/// elsewhere in the body.
///
/// The prefix and suffix never overlap (the suffix is capped at
/// `min(len) - prefix_len`), and both ends are rounded down to UTF-8
/// char boundaries so a span edge can't split a multi-byte char.
fn common_affix_spans(src: &[u8], body: &[u8]) -> Vec<(u32, u32, u32)> {
    let mut spans: Vec<(u32, u32, u32)> = Vec::new();
    let min_len = src.len().min(body.len());
    let mut prefix = src
        .iter()
        .zip(body.iter())
        .take_while(|(a, b)| a == b)
        .count();
    // Round down to a char boundary. The byte AT the prefix end is the
    // first divergent byte, so it can differ between the two sides —
    // check both: a continuation byte (0b10xxxxxx) at the boundary in
    // either means the boundary splits that side's char.
    while prefix > 0
        && ((prefix < body.len() && (body[prefix] & 0xC0) == 0x80)
            || (prefix < src.len() && (src[prefix] & 0xC0) == 0x80))
    {
        prefix -= 1;
    }
    if prefix > 0 {
        spans.push((0, 0, prefix as u32));
    }
    let max_suffix = min_len - prefix;
    let mut suffix = src
        .iter()
        .rev()
        .zip(body.iter().rev())
        .take_while(|(a, b)| a == b)
        .count()
        .min(max_suffix);
    while suffix > 0 && (body[body.len() - suffix] & 0xC0) == 0x80 {
        suffix -= 1;
    }
    if suffix > 0 {
        spans.push((
            (body.len() - suffix) as u32,
            (src.len() - suffix) as u32,
            suffix as u32,
        ));
    }
    spans
}

/// Walk the fragment tree and emit per-construct scaffolding.
///
/// Currently emits a `for`-of loop for each `{#each}` block and recurses
/// into other block bodies / element children. Component-prop excess
/// checks are emitted inline at each `<Component>` position so they
/// sit inside the correct enclosing block scope.
pub(crate) fn emit_template_body(
    buf: &mut EmitBuffer,
    source: &str,
    fragment: &Fragment,
    depth: usize,
    insts: &std::collections::HashMap<u32, &svn_analyze::ComponentInstantiation>,
    action_counter: &mut usize,
) {
    // Hoist `{#snippet name(...)}` names declared at this fragment so
    // sibling component-prop checks (`<X slot={name}>`) resolve them.
    // When any hoist happens, the whole walk is wrapped in a fresh `{}`
    // lexical scope so the declarations don't leak to other fragments
    // at the same depth — e.g. two `<Wrapper>{#snippet action()}...`
    // siblings would otherwise redeclare `action` in the same scope
    // and fire TS2451.
    let snippets: Vec<&SnippetBlock> = fragment
        .nodes
        .iter()
        .filter_map(|n| match n {
            Node::SnippetBlock(b) => Some(b.as_ref()),
            _ => None,
        })
        .collect();
    if snippets.is_empty() {
        for node in &fragment.nodes {
            emit_template_node(buf, source, node, depth, insts, action_counter);
        }
        return;
    }
    let indent = "    ".repeat(depth);
    let _ = writeln!(buf, "{indent}{{");
    for s in &snippets {
        // Consolidated `const NAME = (params): any => { <body> ... };
        // void NAME;` per snippet, hoisted to the top of this block so
        // forward `{@render NAME()}` references resolve. The body is
        // inlined here (instead of a separate `void ((params) => { … })`
        // wrapper at the snippet's textual position) so the user's
        // `(params)` declaration appears exactly once in the overlay,
        // avoiding duplicate `noImplicitAny` diagnostics. Shape is
        // single-sourced in `emit_snippet_const` and mirrors upstream
        // svelte2tsx's `SnippetBlock.ts:117-140`.
        crate::nodes::snippet_block::emit_snippet_const(
            buf,
            source,
            s,
            depth + 1,
            insts,
            action_counter,
        );
    }
    for node in &fragment.nodes {
        // SnippetBlock bodies were inlined into their `const NAME = …`
        // hoist above — skip them here so the body doesn't emit twice.
        if matches!(node, Node::SnippetBlock(_)) {
            continue;
        }
        emit_template_node(buf, source, node, depth + 1, insts, action_counter);
    }
    let _ = writeln!(buf, "{indent}}}");
}

pub(crate) fn emit_template_node(
    buf: &mut EmitBuffer,
    source: &str,
    node: &Node,
    depth: usize,
    insts: &std::collections::HashMap<u32, &svn_analyze::ComponentInstantiation>,
    action_counter: &mut usize,
) {
    match node {
        Node::EachBlock(b) => emit_each_block(buf, source, b, depth, insts, action_counter),
        Node::IfBlock(b) => {
            crate::nodes::if_else_block::emit_if_block(buf, source, b, depth, insts, action_counter)
        }
        Node::AwaitBlock(b) => crate::nodes::await_pending_catch_block::emit_await_block(
            buf,
            source,
            b,
            depth,
            insts,
            action_counter,
        ),
        Node::KeyBlock(b) => {
            crate::nodes::key::emit_key_block(buf, source, b, depth, insts, action_counter)
        }
        Node::SnippetBlock(b) => emit_snippet_block(buf, source, b, depth, insts, action_counter),
        Node::Element(e) => {
            // `<!DOCTYPE html>` parses as a void element named `!DOCTYPE`;
            // it declares the document type, not markup to type-check.
            // Upstream svelte2tsx strips it from the overlay entirely
            // (htmlxtojsx_v2/index.ts `str.remove(node.start, node.end)`).
            // Matched case-insensitively: HTML doctypes are
            // case-insensitive and `<!doctype html>` parses to a
            // lowercase-named element.
            if e.name.eq_ignore_ascii_case("!doctype") {
                return;
            }
            crate::nodes::element::emit_element_node(buf, source, e, depth, insts, action_counter)
        }
        Node::Component(c) => emit_component_node(buf, source, c, depth, insts, action_counter),
        Node::SvelteElement(s) => crate::nodes::element::emit_svelte_element_node(
            buf,
            source,
            s,
            depth,
            insts,
            action_counter,
        ),
        Node::Interpolation(i) => emit_interpolation(buf, source, i, depth),
        Node::Text(_) | Node::Comment(_) => {}
    }
}

pub use is_ts::set_preserve_attribute_case;
pub(crate) use is_ts::{IsTsGuard, emit_is_ts, preserve_attribute_case};
pub(crate) use void_block::{emit_bind_pair_declarations, emit_void_block};

/// For each root snippet, whether upstream hoists it to module scope:
/// there must be a module script, and every free name of the snippet
/// must be allowed there — not declared by the instance script, not a
/// `$$props`-style ambient, not a `$store` subscription (upstream adds
/// every accessed store to the disallowed set), and not another root
/// snippet that itself stays in the component (upstream
/// `HoistableInterfaces.analyzeSnippets`, which iterates until that
/// last set is stable).
fn module_hoistable_snippets(
    root_snippets: &[&svn_parser::SnippetBlock],
    doc: &Document<'_>,
    parsed_instance: Option<&svn_parser::ParsedScript<'_>>,
    parsed_module: Option<&svn_parser::ParsedScript<'_>>,
) -> Vec<bool> {
    if doc.module_script.is_none() || root_snippets.is_empty() {
        return vec![false; root_snippets.len()];
    }
    let mut disallowed: std::collections::HashSet<String> = std::collections::HashSet::new();
    if let Some(p) = parsed_instance {
        svn_analyze::collect_top_level_bindings(&p.program, &mut disallowed);
    }
    // A `$name` reference is a store subscription when `name` is bound
    // by either script; upstream disallows every accessed store.
    let mut script_bound: std::collections::HashSet<String> = disallowed.clone();
    if let Some(p) = parsed_module {
        svn_analyze::collect_top_level_bindings(&p.program, &mut script_bound);
    }
    let globals: Vec<Vec<SmolStr>> = root_snippets
        .iter()
        .map(|s| svn_analyze::snippet_globals(s, doc.source))
        .collect();
    let allowed = |name: &str, disallowed: &std::collections::HashSet<String>| -> bool {
        if matches!(name, "$$props" | "$$restProps" | "$$slots") {
            return false;
        }
        if let Some(base) = name.strip_prefix('$')
            && !base.starts_with('$')
            && script_bound.contains(base)
        {
            return false;
        }
        !disallowed.contains(name)
    };
    let mut hoist = vec![true; root_snippets.len()];
    loop {
        let before = disallowed.len();
        for (i, snippet) in root_snippets.iter().enumerate() {
            if globals[i].iter().all(|g| allowed(g, &disallowed)) {
                continue;
            }
            hoist[i] = false;
            disallowed.insert(snippet.name.to_string());
        }
        if disallowed.len() == before {
            break;
        }
    }
    hoist
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::svelte4::compat::{
        assert_exported_prop_types_in_place, rewrite_definite_assignment_in_place,
    };
    use std::path::PathBuf;
    use svn_analyze::walk_template;
    use svn_parser::{parse_all_template_runs, parse_sections};

    fn def_assign(src: &str, targets: &[&str]) -> String {
        let mut out = String::from(src);
        let targets: Vec<SmolStr> = targets.iter().map(|s| SmolStr::from(*s)).collect();
        rewrite_definite_assignment_in_place(&mut out, &(0..src.len()), &targets);
        out
    }

    fn assert_props(src: &str, targets: &[&str], is_ts: bool) -> String {
        let mut out = String::from(src);
        let targets: Vec<SmolStr> = targets.iter().map(|s| SmolStr::from(*s)).collect();
        assert_exported_prop_types_in_place(&mut out, &(0..src.len()), &targets, None, is_ts);
        out
    }

    #[test]
    fn prop_assertion_after_uninitialized_typed_and_boolean_lets() {
        let got = assert_props(
            "let a;\nlet b: string;\nlet c = false;\nlet d = 1;\n",
            &["a", "b", "c", "d"],
            true,
        );
        assert_eq!(
            got,
            "let a/*svn:ignore_start*/;a = __svn_any(a);/*svn:ignore_end*/;\n\
             let b: string/*svn:ignore_start*/;b = __svn_any(b);/*svn:ignore_end*/;\n\
             let c = false/*svn:ignore_start*/;c = __svn_any(c);/*svn:ignore_end*/;\n\
             let d = 1;\n"
        );
    }

    #[test]
    fn prop_assertion_reads_jsdoc_type() {
        let got = assert_props(
            "/** @type {string} */\nlet a = 'x';\n/** plain */\nlet b = 'y';\n",
            &["a", "b"],
            false,
        );
        assert_eq!(
            got,
            "/** @type {string} */\nlet a = 'x'/*svn:ignore_start*/;a = __svn_any(a);/*svn:ignore_end*/;\n\
             /** plain */\nlet b = 'y';\n"
        );
    }

    #[test]
    fn prop_assertion_follows_multiline_initializer_and_skips_non_targets() {
        let got = assert_props(
            "let label: string =\n\t'a' +\n\t'b';\nlet other: string;\n",
            &["label"],
            true,
        );
        assert_eq!(
            got,
            "let label: string =\n\t'a' +\n\t'b'/*svn:ignore_start*/;label = __svn_any(label);/*svn:ignore_end*/;\n\
             let other: string;\n"
        );
    }

    #[test]
    fn prop_assertion_multi_declarator_appends_once_at_the_end() {
        let got = assert_props("let a, b: string, c = 0;", &["a", "b", "c"], true);
        assert_eq!(
            got,
            "let a, b: string, c = 0/*svn:ignore_start*/;a = __svn_any(a);/*svn:ignore_end*//*svn:ignore_start*/;b = __svn_any(b);/*svn:ignore_end*/;"
        );
    }

    #[test]
    fn def_assign_single_declarator() {
        let got = def_assign("let foo: string;", &["foo"]);
        assert_eq!(got, "let foo!: string;");
    }

    #[test]
    fn def_assign_skips_declaration_with_initializer() {
        // Has `=` before `;` → TS1263 forbids `!`, so leave alone.
        let got = def_assign("let foo: string = 'hi';", &["foo"]);
        assert_eq!(got, "let foo: string = 'hi';");
    }

    #[test]
    fn def_assign_skips_untyped_declaration() {
        // No `:`, no type annotation → no assertion site.
        let got = def_assign("let foo;", &["foo"]);
        assert_eq!(got, "let foo;");
    }

    #[test]
    fn def_assign_skips_non_target_name() {
        let got = def_assign("let other: string;", &["foo"]);
        assert_eq!(got, "let other: string;");
    }

    #[test]
    fn def_assign_multi_declarator_mixed_init() {
        // Core regression: second declarator is uninitialized-typed.
        let got = def_assign(
            "let name3: string = '', name4: string;",
            &["name3", "name4"],
        );
        assert_eq!(got, "let name3: string = '', name4!: string;");
    }

    #[test]
    fn def_assign_multi_declarator_all_need_assertion() {
        let got = def_assign("let a: string, b: number, c: boolean;", &["a", "b", "c"]);
        assert_eq!(got, "let a!: string, b!: number, c!: boolean;");
    }

    #[test]
    fn def_assign_multi_declarator_only_targets_assert() {
        let got = def_assign("let a: string, b: number, c: boolean;", &["a", "c"]);
        assert_eq!(got, "let a!: string, b: number, c!: boolean;");
    }

    #[test]
    fn def_assign_inside_generic_types_not_tripped_by_angle_brackets() {
        // `<T = U>` is a default-type-param, not a let-initializer.
        let got = def_assign("let foo: Map<string, number>;", &["foo"]);
        assert_eq!(got, "let foo!: Map<string, number>;");
    }

    #[test]
    fn def_assign_inside_function_type_not_tripped_by_arrow() {
        let got = def_assign("let foo: () => void;", &["foo"]);
        assert_eq!(got, "let foo!: () => void;");
    }

    #[test]
    fn def_assign_arrow_in_type_plus_initializer_correctly_detected() {
        // Real-world regression: `let foo: (x: T) => R = () => ...;`
        // has a `=` inside `=>`, a `>` after it, AND a real `=` before
        // the initializer. The scanner must not flip paren_depth
        // negative on the arrow's `>`, and must detect the real `=`.
        let got = def_assign("let foo: () => void = () => {};", &["foo"]);
        assert_eq!(got, "let foo: () => void = () => {};", "has init → no !");
    }

    #[test]
    fn def_assign_complex_function_type_with_init() {
        let got = def_assign(
            "let onclick: ((e: MouseEvent) => void) | undefined = undefined;",
            &["onclick"],
        );
        assert_eq!(
            got, "let onclick: ((e: MouseEvent) => void) | undefined = undefined;",
            "union of function type + initializer → no !",
        );
    }

    #[test]
    fn def_assign_fn_type_with_nested_object_and_init() {
        let got = def_assign(
            "let onclick: (e: MouseEvent, { data }: { data: any }) => any = () => {};",
            &["onclick"],
        );
        assert_eq!(
            got, "let onclick: (e: MouseEvent, { data }: { data: any }) => any = () => {};",
            "function type with destructure param + arrow-body init → no !",
        );
    }

    #[test]
    fn def_assign_real_emit_shape() {
        // The exact body shape our emit produces for ts-export-list-runes.v5.
        // ASI-terminated name1 initializer must not swallow name2 through.
        let src = "    let name1: string = \"world\"\n    let name2: string;\n    let name3: string = '', name4: string;\n";
        let got = def_assign(src, &["name1", "name2", "name3", "name4"]);
        // name1 has init → no !. name2, name4 typed-no-init → ! each.
        assert!(
            got.contains("let name2!: string;"),
            "name2 should get !, got: {got:?}"
        );
        assert!(
            got.contains("name4!: string;"),
            "name4 should get !, got: {got:?}"
        );
        assert!(
            got.contains("let name1: string = \"world\""),
            "name1 unchanged (has init): {got:?}"
        );
    }

    #[test]
    fn def_assign_preserves_surrounding_content() {
        let got = def_assign("before();\nlet name: string;\nafter();\n", &["name"]);
        assert_eq!(got, "before();\nlet name!: string;\nafter();\n");
    }

    #[test]
    fn def_assign_not_fooled_by_let_in_comment() {
        // An unclosed `<` or `(` after the word `let` in a comment must
        // not swallow the real declaration below it.
        let src = "// let the parent pick a class for the <span\n\
                   /* We let consumers decide (e.g. \"big\" */\n\
                   let xyz: string;\n";
        let got = def_assign(src, &["xyz"]);
        assert!(got.contains("let xyz!: string;"), "got: {got:?}");
    }

    #[test]
    fn def_assign_leaves_nested_shadowing_let_alone() {
        // A function-local `let` of the same name is a different variable;
        // TS2454 on it is a real error.
        let src = "let el: HTMLElement;\nfunction f() { let el: HTMLElement; return el; }\n";
        let got = def_assign(src, &["el"]);
        assert_eq!(
            got,
            "let el!: HTMLElement;\nfunction f() { let el: HTMLElement; return el; }\n"
        );
    }

    fn emit_str(src: &str) -> String {
        emit_str_with_path(src, "/test/Anonymous.svelte")
    }

    fn emit_str_with_path(src: &str, path: &str) -> String {
        let (doc, errors) = parse_sections(src);
        assert!(errors.is_empty(), "parse errors: {errors:?}");
        let (fragment, errors) = parse_all_template_runs(src, &doc.template.text_runs);
        assert!(errors.is_empty(), "template parse errors: {errors:?}");
        let summary = walk_template(&fragment, src);
        emit_document(&doc, &fragment, &summary, &PathBuf::from(path)).typescript
    }

    #[test]
    fn empty_source_still_emits_scaffold() {
        let out = emit_str("");
        assert!(out.contains("function $$render_"));
        // Template-check body is now `;(async () => { ... });` — see
        // render_function.rs for why (arrow preserves TS narrowing).
        assert!(
            out.contains(";(async () => {"),
            "expected arrow-expression template check body:\n{out}"
        );
    }

    #[test]
    fn render_name_includes_hash_suffix() {
        let out = emit_str("");
        // Scan for the function name and verify it has 8 hex chars after
        // the `$$render_` prefix.
        let idx = out.find("function $$render_").unwrap();
        let tail = &out[idx + "function $$render_".len()..];
        let suffix: String = tail.chars().take(8).collect();
        assert_eq!(suffix.len(), 8, "8-char suffix expected, got {suffix:?}");
        assert!(
            suffix.chars().all(|c| c.is_ascii_hexdigit()),
            "suffix should be hex, got {suffix:?}"
        );
    }

    #[test]
    fn different_paths_produce_different_render_names() {
        let a = emit_str_with_path("<p>hi</p>", "/test/A.svelte");
        let b = emit_str_with_path("<p>hi</p>", "/test/B.svelte");
        // Same content, different paths → different render names. This is
        // what stops the TS2393 cascade across multiple components in one
        // overlay project.
        let a_name = extract_render_name(&a);
        let b_name = extract_render_name(&b);
        assert_ne!(
            a_name, b_name,
            "different paths must hash to different render names"
        );
    }

    #[test]
    fn same_path_produces_stable_render_name() {
        let a1 = emit_str_with_path("<p>hi</p>", "/test/Foo.svelte");
        let a2 = emit_str_with_path("<p>hi</p>", "/test/Foo.svelte");
        assert_eq!(extract_render_name(&a1), extract_render_name(&a2));
    }

    fn extract_render_name(out: &str) -> String {
        let idx = out.find("function $$render_").unwrap();
        let tail = &out[idx + "function ".len()..];
        tail.chars()
            .take_while(|c| *c != '(' && *c != '<')
            .collect()
    }

    #[test]
    fn does_not_emit_svelte_reference_directive() {
        // /// <reference types="svelte" /> would trigger TS2688 in fixtures
        // that don't have the svelte package installed. We rely on the
        // user's environment to have svelte (or our future shim file)
        // rather than asserting it here.
        let out = emit_str("");
        assert!(!out.contains("<reference types=\"svelte\""));
    }

    #[test]
    fn imports_hoisted_above_render_function() {
        let src = "<script lang=\"ts\">\
                   import { writable } from 'svelte/store';\
                   const x = writable(0);\
                   </script>";
        let out = emit_str(src);
        let import_pos = out.find("import { writable }").expect("import present");
        let render_pos = out.find("function $$render_").expect("render present");
        assert!(
            import_pos < render_pos,
            "imports must be hoisted above the render function (found imports at {import_pos}, render at {render_pos})"
        );
    }

    #[test]
    fn imports_only_appear_once() {
        // Hoisted to module top-level — must NOT also appear inside
        // $$render. The body should have whitespace where the import was.
        let src = "<script lang=\"ts\">\
                   import { writable } from 'svelte/store';\
                   const x = writable(0);\
                   </script>";
        let out = emit_str(src);
        let count = out.matches("import { writable }").count();
        assert_eq!(count, 1);
    }

    #[test]
    fn passes_module_script_verbatim() {
        let out = emit_str("<script context=\"module\">export const A = 1;</script>");
        assert!(out.contains("export const A = 1;"));
    }

    #[test]
    fn template_check_wrapper_emits_as_arrow() {
        let out = emit_str("<p>hi</p>");
        // Arrow-expression form (no name to void) — see Gap C.
        assert!(out.contains(";(async () => {"));
        assert!(!out.contains("async function __svn_tpl_check"));
    }

    #[test]
    fn use_directive_emits_action_attrs() {
        let out = emit_str("<div use:tooltip>x</div>");
        assert!(out.contains("__svn_action_attrs_0"));
        assert!(out.contains("let __svn_action_attrs_0"));
    }

    #[test]
    fn bind_pair_emits_bind_pair_declaration() {
        let out = emit_str("<input bind:value={() => g(), (v) => s(v)} />");
        assert!(out.contains("__svn_bind_pair_0"));
        assert!(out.contains("let __svn_bind_pair_0"));
    }

    #[test]
    fn render_function_is_referenced() {
        let out = emit_str("<p>hi</p>");
        // Self-reference is `<render_name>;` on its own line.
        assert!(out.contains("$$render_"));
        let render_name = extract_render_name(&out);
        assert!(out.contains(&format!("{render_name};")));
    }

    #[test]
    fn void_block_uses_per_statement_form() {
        // Switched from `void (a, b, c);` to `void X; void Y; void Z;`
        // — the consolidated form triggers TS2695 ("Left side of comma
        // operator is unused"). Each synthesized name gets its own
        // `void X;` line, and we should never emit the parenthesized
        // multi-name form.
        let out = emit_str("<div use:a use:b>x</div>");
        assert!(
            !out.contains("    void ("),
            "no parenthesized void(...) form expected:\n{out}"
        );
        assert!(out.contains("void __svn_action_attrs_0;"));
        assert!(out.contains("void __svn_action_attrs_1;"));
    }

    #[test]
    fn each_block_without_as_clause_uses_placeholder_binding() {
        let out = emit_str("{#each items}<span>x</span>{/each}");
        assert!(out.contains("for (let"), "missing for-of loop:\n{out}");
        assert!(
            !out.contains("for (let  of"),
            "empty binding produced double-space-before-`of`:\n{out}"
        );
    }

    #[test]
    fn each_block_with_binding_uses_user_name() {
        let out = emit_str("{#each items as item}<span>{item}</span>{/each}");
        assert!(out.contains("for (let item of"));
    }

    #[test]
    fn each_with_destructured_pattern() {
        let out = emit_str("{#each pairs as { a, b }}<x />{/each}");
        assert!(out.contains("for (let"));
        assert!(!out.contains("for (let  of"));
    }

    #[test]
    fn bind_this_target_declaration_is_left_as_written() {
        // Upstream keeps the declaration and assigns the element inside
        // the template arrow, so a direct read still reports TS2454.
        let src = "<script lang=\"ts\">let inputEl: HTMLDivElement;</script>\
                   <div bind:this={inputEl}></div>";
        let out = emit_str(src);
        assert!(out.contains("let inputEl: HTMLDivElement;"), "{out}");
        assert!(
            out.contains("inputEl = /*svn:ignore_start*/null as HTMLElementTagNameMap"),
            "{out}"
        );
    }

    #[test]
    fn non_bind_target_let_unchanged() {
        let src = "<script lang=\"ts\">let other: number = 1;</script>";
        let out = emit_str(src);
        assert!(
            out.contains("let other: number"),
            "non-bind-target should not be rewritten:\n{out}"
        );
        assert!(!out.contains("let other!"));
    }

    #[test]
    fn bind_target_with_initializer_unchanged() {
        let src = "<script lang=\"ts\">let inputEl = null as any as HTMLDivElement;</script>\
                   <div bind:this={inputEl}></div>";
        let out = emit_str(src);
        assert!(
            !out.contains("let inputEl!"),
            "shouldn't add `!` to declarations with initializers:\n{out}"
        );
    }

    #[test]
    fn no_generics_attribute_emits_plain_function() {
        let out = emit_str("<script lang=\"ts\">let x = 1;</script>");
        let render = extract_render_name(&out);
        assert!(out.contains(&format!("{render}() {{")));
        assert!(!out.contains(&format!("{render}<")));
    }

    #[test]
    fn simple_generics_attribute_threaded_into_function_signature() {
        // `<script generics="T">` puts T in scope inside the body.
        let src = "<script lang=\"ts\" generics=\"T\">let x: T;</script>";
        let out = emit_str(src);
        let render = extract_render_name(&out);
        assert!(
            out.contains(&format!("{render}<T>() {{")),
            "generic T should appear in function signature:\n{out}"
        );
    }

    #[test]
    fn generics_with_constraint_threaded_verbatim() {
        let src = "<script lang=\"ts\" generics=\"T extends Record<string, unknown>\">\
                   let x: T;</script>";
        let out = emit_str(src);
        assert!(
            out.contains("<T extends Record<string, unknown>>"),
            "constrained generic should be spliced verbatim:\n{out}"
        );
    }

    #[test]
    fn multiple_generics_threaded() {
        let src = "<script lang=\"ts\" generics=\"T, K extends keyof T\">\
                   let x: T;</script>";
        let out = emit_str(src);
        assert!(
            out.contains("<T, K extends keyof T>"),
            "multi-param generics should be spliced verbatim:\n{out}"
        );
    }

    #[test]
    fn empty_generics_attribute_treated_as_absent() {
        let src = "<script lang=\"ts\" generics=\"\">let x = 1;</script>";
        let out = emit_str(src);
        let render = extract_render_name(&out);
        assert!(out.contains(&format!("{render}() {{")));
        assert!(!out.contains(&format!("{render}<")));
    }
}
